// Generated from assets/ruhh/manifest.json. Do not edit by hand.
class ArtPin {
  const ArtPin({
    required this.id,
    required this.objectName,
    required this.opens,
    required this.x,
    required this.y,
    required this.labelSide,
  });
  final String id;
  final String objectName;
  final String opens;
  final double x;
  final double y;
  final String labelSide;
  String get route {
    switch (opens) {
      case 'habits':
        return '/habit';
      case 'quests':
        return '/quests';
      case 'goals':
        return '/goals';
      case 'evening':
        return '/wrap';
      case 'chat':
        return '/chat';
      default:
        return '/home';
    }
  }
}

class ArtForm {
  const ArtForm({
