ArtWorld artWorldOf(String petId, int world) {
  final id = artForms.containsKey(petId) ? petId : 'dragon';
  final w = world.clamp(1, 5);
  return artWorlds.firstWhere((entry) => entry.petId == id && entry.world == w);
}

ArtForm artFormForLevel(String petId, int level) {
  final id = artForms.containsKey(petId) ? petId : 'dragon';
  final lv = level.clamp(1, 100);
  final forms = artForms[id]!;
  for (final form in forms) {
    if (lv >= form.levelMin && lv <= form.levelMax) return form;
  }
  return forms.last;
}

String artBackdrop(String petId, int world, String screen) {
  final id = artForms.containsKey(petId) ? petId : 'dragon';
  if (id == 'dragon') {
    const map = {
      'habits': 'habits',
      'quests': 'quests',
      'goals': 'goals',
      'money': 'money_ledger',
      'planner': 'planner',
      'journey': 'journey',
      'chat': 'chat_campfire',
      'levelup': 'levelup',
      'morning': 'morning',
      'evening': 'evening',
      'books': 'relics',
      'movies': 'relics',
      'prayer': 'evening',
      'settings': 'world_map',
      'pet': 'world_map',
    };
    final key = map[screen] ?? 'world_map';
    return artBackdrops['dragon/$key']!;
  }
  final band = world.clamp(1, 5);
  return artBackdrops['$id/w${band}_inner']!;
}
